from __future__ import annotations

from typing import Any, Dict, List, Optional, Tuple


def _node(
    nid: str,
    title: str,
    ntype: str,
    agent_id: str,
    prompt: str,
    depends_on: Optional[List[str]] = None,
    tool_preset: str = "research",
    soul_mode: str = "analytical",
    expected_output: str = "",
    forbidden_actions: Optional[List[str]] = None,
) -> Dict[str, Any]:
    return {
        "id": nid,
        "title": title,
        "type": ntype,
        "agent_id": agent_id,
        "tool_preset": tool_preset,
        "soul_mode": soul_mode,
        "prompt": prompt,
        "expected_output": expected_output,
        "forbidden_actions": forbidden_actions or [],
        "depends_on": depends_on or [],
        "require_hitl": ntype == "gate",
    }


def _wf(
    wid: str,
    title: str,
    category: str,
    description: str,
    nodes: List[Dict[str, Any]],
    topic_label: str = "Nische / Thema / Ziel",
    topic_default: str = "",
    schedule_hint: str = "",
) -> Dict[str, Any]:
    return {
        "id": wid,
        "title": title,
        "category": category,
        "description": description,
        "schedule_hint": schedule_hint,
        "n8n_webhook_hint": "",
        "inputs": [{"key": "topic", "label": topic_label, "default": topic_default or title}],
        "builtin": True,
        "nodes": nodes,
    }


def _std4(
    prefix: str,
    s1: Tuple[str, str, str, str],
    s2: Tuple[str, str, str, str],
    s3: Tuple[str, str, str, str],
    s4: Tuple[str, str, str, str],
) -> List[Dict[str, Any]]:
    return [
        _node(f"{prefix}_1", s1[0], s1[1], s1[2], s1[3], []),
        _node(f"{prefix}_2", s2[0], s2[1], s2[2], s2[3], [f"{prefix}_1"]),
        _node(f"{prefix}_3", s3[0], s3[1], s3[2], s3[3], [f"{prefix}_2"], tool_preset="minimal", soul_mode="creative"),
        _node(
            f"{prefix}_4",
            s4[0],
            s4[1],
            s4[2],
            s4[3],
            [f"{prefix}_3"],
            tool_preset="minimal",
            soul_mode="strict",
            forbidden_actions=["Keine externen E-Mails oder Nachrichten ohne Freigabe senden"],
        ),
    ]


